css:
.ro { font-size: 12px; }
.ro .hdr { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #222; padding-bottom: 6px; margin-bottom: 8px; }
.ro .hdr h2 { margin: 0; font-size: 18px; }
.ro .ar { direction: rtl; text-align: right; font-family: 'Tahoma', 'Arial', sans-serif; }
.ro .title { text-align: center; font-size: 16px; font-weight: bold; margin: 6px 0 10px; }
.ro table.kv { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.ro table.kv td { border: 1px solid #999; padding: 4px 6px; vertical-align: top; }
.ro table.kv td.l { width: 18%; background: #f3f3f3; font-weight: bold; }
.ro table.lines { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
.ro table.lines th, .ro table.lines td { border: 1px solid #999; padding: 4px 6px; }
.ro table.lines th { background: #f3f3f3; }
.ro .num { text-align: right; }
.ro .sig { display: flex; justify-content: space-between; margin-top: 28px; }
.ro .sig div { width: 45%; border-top: 1px solid #222; padding-top: 4px; text-align: center; }
.ro .sig img { max-height: 50px; display: block; margin: 0 auto; }
.ro .terms { font-size: 10px; color: #444; margin-top: 10px; }
.tag { width: 70mm; font-size: 11px; border: 1px dashed #222; padding: 4mm; }
.tag .no { font-size: 18px; font-weight: bold; text-align: center; }
.tag .qr { text-align: center; margin: 2mm 0; }
